  const old = relation('r', 'one', 'two', '朋友')
  assert.deepEqual(diffRelations([old], [{ targetCardId: 'two', relationType: '敌人' }]), {
    toRemove: [old], toAdd: [{ targetCardId: 'two', relationType: '敌人' }],
  })
})

